#!/usr/bin/env python3
"""Apply reviewable v2 UI/assessment changes to the v1.1 template. Run once per fresh baseline."""
from pathlib import Path
p=Path(__file__).parent/'template.html'
s=p.read_text(encoding='utf8')

def line(prefix,replacement):
 global s
 lines=s.splitlines(keepends=True)
 matches=[i for i,x in enumerate(lines) if x.lstrip().startswith(prefix)]
 assert len(matches)==1,(prefix,len(matches))
 lines[matches[0]]=replacement.rstrip()+"\n"
 s=''.join(lines)

def replace_exact(old,new):
 global s
 assert old in s,old[:120]
 s=s.replace(old,new)

# Reuse the existing private local-storage key and v1 schema; add optional compatible clinic state.
replace_exact("exams:[],activeExam:null}}", "exams:[],activeExam:null,clinics:{}}}")
replace_exact("const MOD=Object.fromEntries(M.map(x=>[x.id,x])),QMAP=Object.fromEntries(Q.map(x=>[x.id,x]));",
"const MOD=Object.fromEntries(M.map(x=>[x.id,x])),QMAP=Object.fromEntries(Q.map(x=>[x.id,x])),CLINICS=Object.fromEntries((DATA.clinics||[]).map(c=>[c.id,c]));")
# Note: level labels are new metadata; existing question identifiers and user answers remain stable.
newhelpers=r'''
const LEVEL={1:{name:'Foundations',short:'L1 · FOUNDATION',weight:30},2:{name:'Applied understanding',short:'L2 · APPLIED',weight:50},3:{name:'Engineering judgment',short:'L3 · JUDGMENT',weight:20}};
const levelOf=q=>q.level||(q.difficulty==='foundation'?1:2);
const levelTag=q=>`<span class="tag lvl-${levelOf(q)}">${E(LEVEL[levelOf(q)].short)}</span>`;
function evidenceTable(rows){if(!Array.isArray(rows)||!rows.length)return '';return `<div class="scenario-evidence"><div class="eyebrow">OBSERVED EVIDENCE</div><div class="table-wrap"><table class="progress-table"><thead><tr>${rows[0].map(x=>`<th>${E(x)}</th>`).join('')}</tr></thead><tbody>${rows.slice(1).map(r=>`<tr>${r.map(x=>`<td>${E(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`}
function questionStem(q){return `${q.scenario?`<div class="question-scenario"><strong>Engineering scenario</strong><p>${E(q.scenario)}</p></div>`:''}${evidenceTable(q.evidence)}<h2 class="question-prompt">${E(q.question)}</h2>`}
function gradeBreakdown(items,answers){return [1,2,3].map(level=>{const relevant=items.filter(x=>levelOf(QMAP[x.id])===level),n=relevant.filter(x=>answers[x.id]===QMAP[x.id].answer).length;return {level,correct:n,count:relevant.length,pct:relevant.length?Math.round(100*n/relevant.length):0}})}
function sampleLevel(mod,lev,count,avoid=new Set()){const eligible=Q.filter(x=>x.module===mod&&levelOf(x)===lev&&!avoid.has(x.id));
 if(eligible.length<count)throw Error('Not enough level '+lev+' questions in '+mod);
 let rank=lev===2?[...shuffle(eligible.filter(x=>x.quality==='curated')),...shuffle(eligible.filter(x=>x.quality!=='curated'))]:shuffle(eligible);
 return rank.slice(0,count).map(q=>({id:q.id,options:shuffle(q.options)}));}
function sampleBlueprint(mode,module,length){const quotas={1:Math.round(length*.30),2:Math.round(length*.50),3:Math.round(length*.20)};
 if(mode==='section'){const seen=new Set(),selected=[];for(const lev of [1,2,3])for(const rec of sampleLevel(module,lev,quotas[lev],seen)){selected.push(rec);seen.add(rec.id)}return shuffle(selected)}
 const mods=shuffle(M.map(x=>x.id)),per=length/mods.length,allocation=Object.fromEntries(mods.map(x=>[x,[]]));
 // Start each domain with one applied problem; distribute the remaining difficulty quota evenly.
 for(const m of mods)allocation[m].push(2);quotas[2]-=mods.length;
 for(const lev of [3,1,2]){let left=quotas[lev];while(left--){const eligible=shuffle(mods).filter(m=>allocation[m].length<per).sort((a,b)=>{
   let aCount=allocation[a].filter(x=>x===lev).length,bCount=allocation[b].filter(x=>x===lev).length;
   return aCount-bCount||allocation[a].length-allocation[b].length});
   if(!eligible.length)throw Error('Exam blueprint exhausted');allocation[eligible[0]].push(lev);
 }}
 let result=[];for(const mod of mods){let seen=new Set();for(const lev of [1,2,3]){let n=allocation[mod].filter(x=>x===lev).length;for(const rec of sampleLevel(mod,lev,n,seen)){result.push(rec);seen.add(rec.id)}}}
 if(result.length!==length)throw Error('Blueprint count mismatch');return shuffle(result);
}
function levelSummary(items,answers){let breakdown=gradeBreakdown(items,answers);return `<div class="level-summary">${breakdown.map(x=>`<div class="level-mini lvl-${x.level}"><span class="eyebrow">${E(LEVEL[x.level].short)}</span><strong>${x.correct}/${x.count}</strong><small>${x.count?x.pct+'% within level':'No items'}</small></div>`).join('')}</div>`}
function allDistractors(q){let alternatives=q.options.filter(x=>x!==q.answer);return `<details class="alt-analysis"><summary>Why the other options do not fit</summary>${alternatives.map(opt=>`<div class="alt-detail"><b>${E(opt)}</b><p>${E(q.distractor_notes?.[opt]||'Compare this option against the stated evidence, authority boundary and constraints; the correct answer is the one fully supported by them.')}</p></div>`).join('')}</details>`}
'''
replace_exact('const KEY=\'ai-systems-academy-v1\';',newhelpers+"\nconst KEY='ai-systems-academy-v1';")
replace_exact("['concepts','trace','lab','checkpoint'].includes(a[2])", "['concepts','trace','lab','clinic','checkpoint'].includes(a[2])")
replace_exact("'patterns','vocab','labs','capstones','assessment'", "'patterns','vocab','labs','casebook','capstones','assessment'")
replace_exact("${navbtn('labs','Practical labs','flask')}", "${navbtn('labs','Practical labs','flask')}${navbtn('casebook','Engineering clinics','target')}")
replace_exact("labs:'Practice / Labs',assessment:","labs:'Practice / Labs',casebook:'Practice / Engineering clinics',assessment:")
replace_exact("['lab','03 Practical lab'],['checkpoint','04 Checkpoint']", "['lab','03 Practical lab'],['clinic','04 Engineering clinic'],['checkpoint','05 Checkpoint']")
replace_exact("UI.tab==='lab'?labPage(m):checkpointPage(m)", "UI.tab==='lab'?labPage(m):UI.tab==='clinic'?clinicPage(m):checkpointPage(m)")
replace_exact("UI.screen==='labs'?labsHub():UI.screen==='capstones'", "UI.screen==='labs'?labsHub():UI.screen==='casebook'?casebookPage():UI.screen==='capstones'")
# Update surfaced counts and orient the learner from existing home/lesson pages.
line('function stats()', '''function stats(){return `<div class="grid stats"><div class="card stat"><span class="eyebrow">LEARNING</span><span class="num">${M.reduce((n,m)=>n+m.topics.length,0)}</span><span class="cap">connected concept lessons</span><span class="meta">${DATA.clinics.length} evidence-driven clinics · 30 stages</span></div><div class="card stat"><span class="eyebrow">PRACTICE</span><span class="num">10</span><span class="cap">hands-on labs</span><span class="meta">self-evidenced practice</span></div><div class="card stat"><span class="eyebrow">RECALL</span><span class="num">${V.length}</span><span class="cap">technical vocabulary cards</span><span class="meta">spaced retrieval practice</span></div><div class="card stat"><span class="eyebrow">ASSESS</span><span class="num">${Q.length}</span><span class="cap">four-option questions</span><span class="meta">L1 ${Q.filter(x=>levelOf(x)===1).length} · L2 ${Q.filter(x=>levelOf(x)===2).length} · L3 ${Q.filter(x=>levelOf(x)===3).length}</span></div></div>`}''')
replace_exact("<h3 style=\"margin:8px 0 14px\">Read → Trace → Build → Check → Recall</h3>","<h3 style=\"margin:8px 0 14px\">Read → Trace → Build → Diagnose → Check → Recall</h3>")
replace_exact("${docbanner()}${footer()}`}","<div class=\"doc-banner\"><div><strong>New: evidence-driven engineering clinics</strong><p>Practice real diagnosis, evaluate measurements and defend architecture decisions across all ten modules.</p></div><button class=\"btn ghost small\" data-screen=\"casebook\">Explore casebook ${I('arrow','sm')}</button></div>${docbanner()}${footer()}`}")

# Add complete integrated engineering-clinic learning experience.
clinicfunctions=r'''
function clinicRecord(id){if(!S.clinics)S.clinics={};if(!S.clinics[id])S.clinics[id]={answers:{}};return S.clinics[id]}
function clinicCount(c){return Object.keys(S.clinics?.[c.id]?.answers||{}).length}
function casebookPage(){return `<div class="section-head"><div><div class="eyebrow">10 ENGINEERING CLINICS · 30 GUIDED DECISIONS</div><h1 style="margin:7px 0">Learn by diagnosing real boundaries.</h1><p>Each case provides observed measurements, constraints, three increasingly difficult decisions, explanations for the alternatives and a reproducible evidence target. Practice is unscored.</p></div></div><div class="grid two-col">${DATA.clinics.map(c=>`<article class="card card-pad clinic-card"><div class="linkrow" style="justify-content:space-between"><span class="tag">${E(MOD[c.id].title.slice(0,2))} · ENGINEERING CLINIC</span><span class="pill ${clinicCount(c)===3?'pass':'neutral'}">${clinicCount(c)}/3 stages</span></div><h3>${E(c.title)}</h3><p>${E(c.objective)}</p><button class="btn primary small" data-clinic-mod="${E(c.id)}">${clinicCount(c)?'Continue case':'Work this case'} ${I('arrow','sm')}</button></article>`).join('')}</div>${footer()}`}
function clinicPage(m){const c=CLINICS[m.id];if(!c)return `<div class="empty">No clinic for this module.</div>`;const r=S.clinics?.[m.id]||{answers:{}};
 let answered=Object.keys(r.answers).length;return `<div class="section-head"><div><div class="eyebrow">EVIDENCE-DRIVEN CASE STUDIO · ${E(m.title)}</div><h2>${E(c.title)}</h2><p>${E(c.objective)}</p></div><span class="pill ${answered===3?'pass':'neutral'}">${answered}/3 stages explored</span></div><div class="card card-pad"><div class="eyebrow">SCENARIO</div><p class="clinic-story">${E(c.story)}</p>${evidenceTable(c.evidence)}<div class="detail-grid" style="margin-top:18px"><div class="detail-box"><h4>Engineering constraints</h4><ul>${c.constraints.map(x=>`<li>${E(x)}</li>`).join('')}</ul></div><div class="detail-box"><h4>Evidence to produce</h4><p>${E(c.proof)}</p></div></div></div><div class="clinic-rail">${c.steps.map((st,i)=>{let selected=r.answers[i],has=Object.prototype.hasOwnProperty.call(r.answers,i);return `<section class="card card-pad clinic-stage" id="clinic-stage-${i}"><div class="question-meta"><span class="tag lvl-${i===0?1:i===1?2:3}">${E(st.stage)}</span><span class="fine">${has?'Reviewed · feedback available':'Analyze before choosing'}</span></div><h3>${E(st.question)}</h3><div class="question-options">${st.options.map((opt,j)=>`<button class="answer ${has?(opt===st.answer?'correct':opt===selected?'wrong':''):''}" data-clinic-answer="${i}" data-opt="${E(opt)}" ${has?'disabled':''}><span class="letter">${'ABCD'[j]}</span><span>${E(opt)}</span></button>`).join('')}</div>${has?`<div class="feedback ${selected===st.answer?'':'wrong'}"><strong>${selected===st.answer?'Evidence-supported answer':'Inspect the reasoning'}</strong><p>${E(st.explanation)}</p><div class="learning-deeper"><p><strong>Transfer insight:</strong> ${E(st.insight)}</p>${allDistractors(st)}</div><button class="txtbtn" data-clinic-retry="${i}">Try this stage again</button></div>`:`<p class="fine">Choose the most defensible answer. The rationale appears immediately; this is learning mode.</p>`}</section>`}).join('')}</div><div class="callout"><strong>${answered===3?'Case explored · now transfer the skill':'Turn the case into engineering evidence'}</strong><p>${E(c.proof)}</p><div class="rel-links">${c.connections.map(id=>`<button class="rel-btn" data-mod="${E(id)}">${E(MOD[id]?.title.slice(5)||id)} ${I('arrow','sm')}</button>`).join('')}<button class="rel-btn" data-tab="checkpoint">Module knowledge check ${I('arrow','sm')}</button></div></div>`}
'''
replace_exact('function assessment(){',clinicfunctions+'\nfunction assessment(){')

# Three-level exam contract is exact for 20/30/40 items; section sample same ratio.
line('function assessment()', '''function assessment(){if(S.activeExam)return examUI();if(UI.guided)return guidedUI();return `<div class="section-head"><div><div class="eyebrow">3-LEVEL MASTERY · 80% PASS · EVIDENCE BEFORE CONFIDENCE</div><h1 style="margin:7px 0">Knowledge is the beginning. Judgment is the test.</h1><p>Scored exams contain 30% foundations, 50% applied understanding and 20% engineering judgment. Getting Levels 1 and 2 entirely right reaches exactly 80%; Level 3 is how you reach 100%. Answers and hints remain hidden until submission.</p></div></div><div class="grid three-col">${[[1,'Identify concepts and boundaries'],[2,'Interpret evidence and diagnose'],[3,'Defend architecture under constraints']].map(([l,desc])=>`<div class="card stat"><span class="eyebrow">LEVEL ${l} · ${LEVEL[l].name}</span><span class="num">${LEVEL[l].weight}%</span><span class="cap">${E(desc)}</span><span class="meta">${Q.filter(x=>levelOf(x)===l).length} items available</span></div>`).join('')}</div><div class="exam-selection" style="margin-top:19px"><div class="card exam-choice"><span class="eyebrow">CROSS-DOMAIN EXAM</span><h2 style="margin:13px 0">Full architecture assessment</h2><p>20, 30 or 40 questions. Every module represented equally. Exact L1/L2/L3 weighting and shuffled alternatives, with more reasoning-heavy curated cases.</p><div class="field"><label for="examLength">Questions in exam</label><select id="examLength">${[20,30,40].map(x=>`<option value="${x}" ${UI.examLength===x?'selected':''}>${x} questions</option>`).join('')}</select></div><div style="margin-top:15px"><button class="btn primary" data-action="start-full-exam">${I('play')} Start full exam</button></div></div><div class="card exam-choice"><span class="eyebrow">FOCUSED EXAM</span><h2 style="margin:13px 0">One-module assessment</h2><p>20 unique questions: six L1, ten L2 and four L3. A successful score demands strong applied reasoning, not just memorized terminology.</p><div class="field"><label for="examModule">Select module</label><select id="examModule">${M.map(m=>`<option value="${m.id}" ${m.id===UI.examModule?'selected':''}>${E(m.title)}</option>`).join('')}</select></div><div style="margin-top:15px"><button class="btn primary" data-action="start-section-exam">${I('play')} Start section exam</button></div></div></div><div class="card card-pad guided-choice"><div class="eyebrow">LEARN BEFORE YOU ARE GRADED</div><h2 style="margin:10px 0">Guided architecture challenge</h2><p>Ten questions, one per domain, progressing through the three levels. Reveal a hint, choose an answer, explore every alternative and follow the connected concepts. No exam score is recorded.</p><div class="linkrow" style="flex-wrap:wrap;gap:9px"><button class="btn primary" data-action="start-guided">${I('play')} Start guided challenge</button><button class="btn ghost" data-screen="casebook">${I('target')} Open the 10 engineering clinics</button></div></div><div class="card card-pad" style="margin-top:17px"><h3>How to interpret a result</h3><div class="grid three-col"><div><strong>Foundations · 30%</strong><p style="font-size:12px">Essential distinctions and vocabulary.</p></div><div><strong>Applied · 50%</strong><p style="font-size:12px">Measured data, diagnosis and failure boundaries.</p></div><div><strong>Judgment · 20%</strong><p style="font-size:12px">Architectural trade-offs and safety decisions.</p></div></div><p class="fine" style="margin-top:13px">A score is an educational indicator, not certification. Real-world expertise also needs tested labs, measured capstones and independent review. Option order is randomized; do not infer correctness from answer position or length.</p></div>${S.exams.length?`<div class="section-head"><h2>Recent attempts</h2><button class="txtbtn" data-screen="progress">All results ${I('arrow','sm')}</button></div><div class="grid three-col">${S.exams.slice().reverse().slice(0,3).map(x=>`<div class="card card-pad"><span class="pill ${x.passed?'pass':'fail'}">${x.passed?'Pass':'Not passed'}</span><h3 style="margin:12px 0">${x.percent}% · ${x.score}/${x.count}</h3><p style="font-size:12px">${E(x.mode==='full'?'Full assessment':MOD[x.module].title)} · ${date(x.date)}</p><button class="txtbtn" data-review="${x.id}">Review answers ${I('arrow','sm')}</button></div>`).join('')}</div>`:''}${footer()}`}''')
line('function startGuided()', '''function startGuided(){const mods=shuffle(M.map(m=>m.id));const levels=shuffle([1,1,1,2,2,2,2,2,3,3]);const items=shuffle(mods.map((m,i)=>sampleLevel(m,levels[i],1)[0]));UI.guided={items,index:0,answers:{},hints:{},finished:false};UI.screen='assessment';render();window.scrollTo(0,0)}''')
line('function createExam(', '''function createExam(mode,mod,length){if(S.activeExam&&!confirm('Replace the current unfinished exam?'))return;const chosen=sampleBlueprint(mode,mod,length);S.activeExam={id:uid(),mode,module:mode==='section'?mod:null,count:chosen.length,items:chosen,index:0,answers:{},date:Date.now(),blueprint:{level1:Math.round(length*.3),level2:Math.round(length*.5),level3:Math.round(length*.2)}};save();UI.screen='assessment';render();window.scrollTo(0,0)}''')
line('function examUI()', '''function examUI(){let ex=S.activeExam,rec=ex.items[ex.index],q=QMAP[rec.id],answered=Object.keys(ex.answers).length;return `<div class="exam-head"><div><div class="eyebrow">SCORED ASSESSMENT · ${E(ex.mode==='full'?'ALL TEN MODULES':MOD[ex.module].title)}</div><h2 style="margin:6px 0">Question ${ex.index+1} of ${ex.count}</h2></div><span class="pill neutral">${answered}/${ex.count} answered</span></div><div class="exam-layout"><div class="card question"><div class="question-meta">${levelTag(q)}<span class="fine">Domain: ${E(MOD[q.module].title.slice(5))}</span></div>${questionStem(q)}<div class="question-options">${rec.options.map((x,i)=>`<button class="answer ${ex.answers[rec.id]===x?'selected':''}" data-exam-answer="${E(x)}"><span class="letter">${'ABCD'[i]}</span><span>${E(x)}</span></button>`).join('')}</div><div class="lesson-next"><button class="btn ghost" data-action="exam-prev" ${ex.index===0?'disabled':''}>${I('back','sm')} Previous</button>${ex.index===ex.count-1?`<button class="btn primary" data-action="submit-exam">${I('check','sm')} Submit exam</button>`:`<button class="btn primary" data-action="exam-next">Next question ${I('arrow','sm')}</button>`}</div></div><aside class="card exam-sidebar"><div class="eyebrow">EXAM NAVIGATION</div><h3 style="margin:8px 0">Answer map</h3><div class="bar" style="margin:0 0 17px"><i style="width:${Math.round(100*answered/ex.count)}%"></i></div><div class="exam-index">${ex.items.map((item,i)=>`<button aria-label="Go to question ${i+1}" class="${ex.index===i?'current':ex.answers[item.id]?'answered':''}" data-exam-go="${i}">${i+1}</button>`).join('')}</div><p class="fine" style="margin:18px 0">${levelTag(q)} · No hints or correctness feedback until submission. Navigate and revise answers freely.</p><button class="btn primary" style="width:100%" data-action="submit-exam">${I('check','sm')} Submit exam</button><button class="txtbtn" style="margin-top:17px;color:#a55c62" data-action="abandon-exam">Discard attempt</button></aside></div>`}''')
line('function submitExam()', '''function submitExam(){let ex=S.activeExam;if(!ex)return;let n=Object.keys(ex.answers).length;if(n<ex.count&&!confirm(`${ex.count-n} question(s) unanswered. Submit with those counted incorrect?`))return;let items=ex.items.map(x=>({id:x.id,selected:ex.answers[x.id]??null}));let score=items.filter(x=>x.selected===QMAP[x.id].answer).length,percent=Math.round(100*score/ex.count);let result={id:ex.id,date:Date.now(),mode:ex.mode,module:ex.module,count:ex.count,score,percent,passed:score/ex.count>=.80,items,levels:gradeBreakdown(ex.items,ex.answers)};S.exams.push(result);S.exams=S.exams.slice(-35);S.activeExam=null;save();UI.reviewId=result.id;UI.screen='results';UI.reviewWrongOnly=false;location.hash='results';render();window.scrollTo(0,0)}''')

# Update learning-first results, and present per-level diagnosis and direct remediation.
line('function resultView()', '''function resultView(){let r=S.exams.find(x=>x.id===UI.reviewId)||S.exams.at(-1);if(!r)return `<div class="empty">No scored exam results yet. <button class="txtbtn" data-screen="assessment">Start an exam</button></div>`;let wrong=r.items.filter(x=>x.selected!==QMAP[x.id].answer),visible=UI.reviewWrongOnly?wrong:r.items;const answers=Object.fromEntries(r.items.map(x=>[x.id,x.selected]));const levels=gradeBreakdown(r.items,answers);const weakest=[...new Set(wrong.map(x=>QMAP[x.id].module))];return `<div class="results-summary"><span class="eyebrow" style="color:#96d3ce">EXAM OUTCOME · ${date(r.date)}</span><div class="big">${r.percent}%</div><span class="pill ${r.passed?'pass':'fail'}">${r.passed?'PASS · 80% MET':'NOT PASSED · 80% REQUIRED'}</span><p style="margin-top:15px">${r.score} correct of ${r.count} questions · ${E(r.mode==='full'?'Cross-domain assessment':MOD[r.module].title)}. Level 1 and 2 together make up 80% of the exam; Level 3 is necessary for a perfect score.</p><div class="linkrow" style="margin-top:18px"><button class="btn hero-primary" data-screen="assessment">Take another exam ${I('arrow','sm')}</button><button class="btn hero-ghost" data-screen="casebook">Engineering clinics</button></div></div><div class="section-head"><h2>Mastery by difficulty</h2><span class="fine">Each level has a different engineering purpose.</span></div><div class="level-summary">${levels.map(x=>`<div class="card card-pad level-mini lvl-${x.level}"><span class="eyebrow">${LEVEL[x.level].short}</span><strong>${x.correct}/${x.count}</strong><span class="fine">${x.pct}% correct within level · weight ${LEVEL[x.level].weight}%</span></div>`).join('')}</div>${weakest.length?`<div class="card card-pad" style="margin-top:18px"><span class="eyebrow">TARGETED NEXT STEPS</span><h3>Learn from the questions that did not land.</h3><p>Review the case studio and key concepts in each affected domain. Answering the same questions again immediately may measure memorization rather than transferable understanding.</p><div class="rel-links">${weakest.map(id=>`<button class="rel-btn" data-clinic-mod="${id}">Clinic: ${E(MOD[id].title.slice(5))} ${I('arrow','sm')}</button>`).join('')}</div></div>`:`<div class="callout"><strong>All answers supported in this sample.</strong><p>A perfect quiz does not establish production mastery. Validate your ability to produce independent evidence in a capstone.</p></div>`}<div class="section-head"><h2>Review the engineering reasoning</h2><div class="filterbar" style="margin:0"><button class="btn small ${UI.reviewWrongOnly?'primary':'ghost'}" data-action="review-wrong">Missed only</button><button class="btn small ${!UI.reviewWrongOnly?'primary':'ghost'}" data-action="review-all">All questions</button></div></div>${visible.length?visible.map((x,i)=>{let q=QMAP[x.id],ok=x.selected===q.answer;return `<div class="result-row"><div class="question-meta"><span class="pill ${ok?'pass':'fail'}">${ok?'Correct':'Needs review'}</span>${levelTag(q)}<span class="fine">${E(MOD[q.module].title.slice(5))}</span></div>${questionStem(q)}<p>Your answer: <strong>${E(x.selected||'Not answered')}</strong></p><p>Best answer: <strong>${E(q.answer)}</strong></p><p class="why">${E(q.explanation)}</p>${learningPanel(q,x.selected)}${allDistractors(q)}<div class="linkrow" style="gap:15px;flex-wrap:wrap"><button class="txtbtn" data-term="${E(q.term)}">Review: ${E(q.term)} ${I('arrow','sm')}</button><button class="txtbtn" data-clinic-mod="${q.module}">Apply: engineering clinic ${I('arrow','sm')}</button>${Number.isInteger(q.lesson)?`<button class="txtbtn" data-concept="${q.module}:${q.lesson}">Read the linked concept</button>`:''}</div></div>`}).join(''):`<div class="empty">No missed questions in this attempt. Inspect all items or try a fresh exam.</div>`}${docbanner()}${footer()}`}''')

# Include scenarios and constructive distractor review in checkpoints and guided learning.
replace_exact('<h2>${E(q.question)}</h2><div class="question-options">','${questionStem(q)}<div class="question-options">')
replace_exact('<h3 style="margin:10px 0">${i+1}. ${E(q.question)}</h3>','<h3 style="margin:10px 0">${i+1}. ${E(q.question)}</h3>${evidenceTable(q.evidence)}')
replace_exact('<h3>${E(q.question)}</h3><p>Your answer:', '<h3>${E(q.question)}</h3>${evidenceTable(q.evidence)}<p>Your answer:')
# More explanatory alternatives after answering.
